package me.trossty.car.sound;

import me.trossty.car.CarMain;
import net.minecraft.registry.Registries;
import net.minecraft.registry.Registry;
import net.minecraft.registry.entry.RegistryEntry;
import net.minecraft.sound.SoundEvent;
import net.minecraft.util.Identifier;

/**
 * Sounds the car uses.
 *
 * <p>Both are our own synthesized audio, not vanilla events. The sources live in
 * {@code sounds-src/} and are regenerated by {@code sounds-src/GenSounds.java};
 * the shipped {@code .ogg} files sit in {@code assets/car/sounds/} and are
 * declared in {@code assets/car/sounds.json}.
 *
 * <p>Both files are <strong>mono</strong> on purpose: Minecraft only pans and
 * attenuates single-channel audio. A stereo file would play at full volume
 * everywhere, so the car's engine would be audible across the whole world.
 */
public final class ModSounds {

    /**
     * Looping engine drone, a 70 Hz fundamental with eight harmonics over a
     * seamless one-second loop. Pitched between IDLE_PITCH and MAX_PITCH by
     * speed, so pitch 1.0 is the idle note as synthesized.
     */
    public static final SoundEvent CAR_ENGINE = register("engine");

    /** One-shot horn blast: a 440 Hz / 554.37 Hz two-tone chord. */
    public static final RegistryEntry<SoundEvent> CAR_HORN = registerReference("horn");

    /** Tyre squeal for a car sliding sideways: a wavering whine over hiss. */
    public static final SoundEvent TYRE_SKID = register("skid");

    /** A cross-plane V8's loping burble, 46 Hz, for the big engines. */
    public static final SoundEvent ENGINE_V8 = register("engine_v8");

    /** A diesel's drone with a knock at every firing. */
    public static final SoundEvent ENGINE_DIESEL = register("engine_diesel");

    /** An electric motor's inverter whine: no firing, just a clean rising tone. */
    public static final SoundEvent ENGINE_ELECTRIC = register("engine_electric");

    /** A generator set running, played now and then while it burns. */
    public static final SoundEvent GENERATOR_HUM = register("generator_hum");

    /** The pumpjack's beam: a thump and a long creak. */
    public static final SoundEvent PUMPJACK_CREAK = register("pumpjack_creak");

    /** Crude boiling in the refinery's column, and the hydrotreater's reactor. */
    public static final SoundEvent REFINERY_BUBBLE = register("refinery_bubble");

    /** A charging post putting power into a car. */
    public static final SoundEvent CHARGER_HUM = register("charger_hum");

    private ModSounds() {
    }

    private static SoundEvent register(String path) {
        Identifier id = CarMain.id(path);
        return Registry.register(Registries.SOUND_EVENT, id, SoundEvent.of(id));
    }

    private static RegistryEntry.Reference<SoundEvent> registerReference(String path) {
        Identifier id = CarMain.id(path);
        return Registry.registerReference(Registries.SOUND_EVENT, id, SoundEvent.of(id));
    }

    /** Forces class loading so the static fields above are registered. */
    public static void register() {
    }
}
